                values: new object[] { "Hafta 1: Python'a Giriş ve Değişkenler\nHafta 2: Kontrol Yapıları ve Döngüler\nHafta 3: Fonksiyonlar ve Modüler Programlama\nHafta 4: Nesne Yönelimli Programlama (OOP)\nHafta 5: Dosya İşlemleri ve Veri Tabanı\nHafta 6: Veri Analizi Temelleri (Pandas & Numpy)\nHafta 7: Yapay Zeka ve ML Giriş (Scikit-Learn)\nHafta 8: Bitirme Projesi ve Sertifika Töreni", "Geleceğin dünyasını kodlamaya hazır mısınız? Bu kurs, Python'un gücünü Yapay Zeka (AI) ile birleştirerek size eşsiz bir kariyer kapısı açıyor. Veri biliminden otomasyona kadar modern teknolojinin kalbinde yer alacaksınız. Sadece öğrenmekle kalmayacak, üreteceksiniz!", new DateTime(2026, 7, 25, 0, 0, 0, 0, DateTimeKind.Unspecified), "Sıfırdan İleri Seviye Python Geliştirme\nYapay Zeka ve Makine Öğrenmesi Modelleri\nBüyük Veri Analizi ve Görselleştirme\nAkıllı Sohbet Botları (Chatbot) Tasarımı\nOtomatik Veri Madenciliği ve Raporlama" });

