                values: new object[] { "Profesyonel Pastacılık ve Ekmekçilik", "Hafta 1: Pastacılık Malzemeleri ve Hijyen\nHafta 2: Pandispanya ve Temel Kekler\nHafta 3: Pasta Kremaları ve Ganaj Yapımı\nHafta 4: Şeker Hamuru ile Figür Tasarımı\nHafta 5: Tartlar, Kişler ve Kurabiyeler\nHafta 6: Mayalı Hamurlar ve Açma/Poğaça\nHafta 7: Dünya Tatlıları (Tiramisu, Cheesecake)\nHafta 8: Katlı Pasta Yapımı ve Sunum", "Tatlı bir kariyer başlangıcı yapın! Pasta süsleme tekniklerinden artisan ekmek yapımına kadar her şeyi uygulamalı olarak göreceksiniz. Kendi butik pastanenizi açma hayalinize bir adım daha yaklaşın.", new DateTime(2026, 8, 10, 0, 0, 0, 0, DateTimeKind.Unspecified), "Temel Hamur ve Krema Teknikleri\nButik Pasta Tasarımı ve Süsleme\nArtisan (Ekşi Mayalı) Ekmek Yapımı\nÇikolata İşleme ve Şeker Sanatı\nMaliyet Hesaplama ve İşletme Bilgisi" });

